(390, 99, 'a', 'Aspek pertama mengonfirmasi kematian. Beri tahu perusahaan dan keluarga terdekat, dan jika ada di kapal, beri tahu dan beri penghiburan sesuai kebutuhan. Atur agar jenazah dipindahkan ke ruang pendingin. Beri tahu agen lokal dan Konsul Inggris jika berada di luar negeri. Catat dalam Catatan Kelahiran dan Kematian.', 0, '0', NULL),
(391, 99, 'b', 'Konfirmasikan kematian. Pindahkan jenazah ke kompartemen freezer. Hubungi agen setempat dan Konsul Inggris jika diperlukan. Lengkapi bagian naratif buku catatan resmi. Buat entri di buku catatan dek yang merinci tindakan yang diambil.', 0, '0', NULL),
(392, 99, 'c', 'Konfirmasikan kematian. Hubungi agen setempat dan atur evakuasi jenazah dari kapal. Beri tahu perusahaan. Lengkapi bagian kelahiran dan kematian di buku catatan resmi.', 0, '0', NULL),
(393, 99, 'd', 'Konfirmasikan kematian. Beri tahu keluarga terdekat, dan jika sudah di pesawat, beri penghiburan seperlunya. Catat di bagian Kelahiran dan Kematian di OLB, dan catat di bagian narasi OLB. Beri tahu agen dan Konsul Inggris jika di luar negeri. Miliki tempat tinggal.', 0, '0', NULL),
