(998, 251, 'a', 'Ini adalah kapal yang melakukan pengerukan atau operasi bawah air. Dua bola dalam garis vertikal menunjukkan sisi aman untuk dilewati; dua belah ketupat dalam garis vertikal menunjukkan sisi yang memiliki halangan; bola/belah ketupat/bola menunjukkan kapal dibatasi dalam kemampuannya untuk bermanuver.', 0, '0', NULL),
(999, 251, 'b', 'Ini adalah kapal yang bertugas keamanan pelabuhan. Dua bola dalam garis vertikal menunjukkan pelabuhan ditutup; dua belah ketupat dalam garis vertikal menunjukkan pelabuhan sedang melakukan operasi pembersihan ranjau; bola/belah ketupat/bola menunjukkan kapal tersebut dibatasi dalam kemampuannya untuk bermanuver.', 0, '0', NULL),
(1000, 251, 'c', 'Ini adalah kapal yang melakukan pengerukan atau operasi bawah air. Dua bola dalam garis vertikal menunjukkan sisi di mana terdapat halangan; dua belah ketupat dalam garis vertikal menunjukkan sisi yang aman untuk dilewati; kombinasi bola/belah ketupat/bola secara vertikal menunjukkan bahwa kapal tersebut dibatasi dalam kemampuannya untuk bermanuver.', 0, '0', NULL),
(1001, 251, 'd', 'Ini adalah kapal yang melakukan operasi pembersihan ranjau. Dua bola dalam garis vertikal menunjukkan alat penyapu aktif; dua belah ketupat dalam garis vertikal menunjukkan bahwa kapal harus diberi jarak minimal 1.000 meter; bola/belah ketupat/bola menunjukkan kapal tersebut dibatasi dalam kemampuannya untuk bermanuver.', 0, '0', NULL),
