(1344, 354, 'a', 'Saya kadang memilih cara kerja yang terasa lebih menguntungkan bagi diri saya, meskipun tidak sepenuhnya sesuai dengan prosedur.', 0, '0', NULL),
(1345, 354, 'b', 'Saya tetap mengikuti prosedur yang berlaku, meskipun ada cara lain yang terlihat lebih cepat atau menguntungkan.', 1, '0', NULL),
(1346, 355, 'a', 'Saya cenderung menilai dan mempertimbangkan setiap permintaan sebelum memutuskan mengikuti atau tidak.', 1, '0', NULL),
(1347, 355, 'b', 'Saya cenderung mengikuti arahan atasan meskipun terkadang merasa itu tidak sepenuhnya benar.', 0, '0', NULL),
(1348, 356, 'a', 'Saya merasa cukup mampu menangani dampak dari keputusan atau tindakan yang berisiko.', 0, '0', NULL),
(1349, 356, 'b', 'Saya cenderung berhati-hati karena tahu tidak semua akibat dari keputusan bisa saya kendalikan.', 1, '0', NULL),
