(1352, 358, 'a', 'Dalam kondisi terdesak, saya akan mempertimbangkan menggunakan dana perusahaan terlebih dahulu dengan rencana segera melaporkan dan menggantinya.', 1, '0', NULL),
(1353, 358, 'b', 'Dana perusahaan tidak seharusnya digunakan untuk keperluan pribadi, meskipun dalam situasi mendesak.', 0, '0', NULL),
(1354, 359, 'a', 'Saya percaya standar moral seseorang tidak didasarkan dengan tingkat penghasilan individu.', 0, '0', NULL),
(1355, 359, 'b', 'Saya memahami bahwa tekanan ekonomi dapat mempengaruhi pilihan moral seseorang.', 1, '0', NULL),
(1356, 360, 'a', 'Saya lebih nyaman bekerja tanpa perlu banyak pengawasan sehingga saya lebih bebas mengambil keputusan sendiri.', 1, '0', NULL),
(1357, 360, 'b', 'Saya merasa lebih tenang bekerja dengan pengawasan serta arahan yang jelas.', 0, '0', NULL),
(1358, 361, 'a', 'Saya menyampaikan pendapat meski tahu bisa berbeda dari kebanyakan orang.', 1, '0', NULL),
