(1363, 363, 'b', 'Saya cenderung menyiapkan rencana dengan jelas sebelum mengambil langkah.', 0, '0', NULL),
(1364, 364, 'a', 'Saya lebih memilih memberi ruang kepada rekan untuk memperbaiki kesalahannya sebelum dilaporkan secara formal.', 1, '0', NULL),
(1365, 364, 'b', 'Saya cenderung melaporkan pelanggaran jika sudah cukup jelas dan berdampak pada pekerjaan.', 0, '0', NULL),
