--
-- Table structure for table `questions`
--

CREATE TABLE `questions` (
  `question_id` int NOT NULL,
  `role` text NOT NULL COMMENT 'va_1, va_2, va_3, kkm, etc.',
  `question_text` text NOT NULL,
  `category` varchar(100) DEFAULT NULL COMMENT 'For VA_1 only',
  `is_image` text,
  `image_url` varchar(500) DEFAULT NULL,
  `assessment_id` bigint UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

--
-- Dumping data for table `questions`
--

INSERT INTO `questions` (`question_id`, `role`, `question_text`, `category`, `is_image`, `image_url`, `assessment_id`) VALUES
(1, 'kkm', 'Mengapa petugas yang memiliki kualifikasi yang memadai harus mengawasi operasi apa pun yang berpotensi menimbulkan polusi?', NULL, NULL, NULL, 4),
(2, 'kkm', 'Entalpi adalah ekspresi jumlah energi yang terikat dalam satu kilogram suatu zat. Total energi suatu zat terdiri dari:', NULL, NULL, NULL, 4),
(3, 'kkm', 'Sebuah tangki berlapis menampung 400 ton air laut saat terisi penuh. Berapa ton cairan dengan berat 0,9300 liter yang dapat ditampungnya saat terisi penuh hingga 90%?', NULL, NULL, NULL, 4),
(4, 'kkm', 'Rangkaian ini terdiri dari sumber tegangan V, sakelar pengubah S, resistor R, dan kapasitor C. Gambar tegangan/waktu 1 hingga 4 menunjukkan perubahan tegangan V (C) ketika sakelar S tiba-tiba dipindahkan dari posisi 1 ke 2 pada waktu t = 0. Hanya satu diagram yang benar. Manakah yang benar?', NULL, NULL, NULL, 4),
(5, 'kkm', 'Mengapa semua kapal penumpang RoRo dibagi menjadi “zona” vertikal?', NULL, NULL, NULL, 4),
(6, 'kkm', 'Apa nama kimia yang tepat untuk Soda Kaustik dalam bentuk cair?', NULL, NULL, NULL, 4),
(7, 'kkm', 'Manual Pelatihan harus berisi instruksi dan informasi tentang peralatan penyelamat jiwa dan metode terbaik untuk bertahan hidup. Manual pelatihan harus berisi penjelasan rinci tentang tugas kru terkait situasi darurat. Manakah dari tugas atau kewajiban berikut yang harus dimasukkan dalam manual sesuai dengan peraturan yang berlaku?', NULL, NULL, NULL, 4),
(8, 'kkm', 'Pada interval kalender berapakah peralatan pengangkat di atas kapal harus diuji secara tepat oleh orang yang berkompeten?', NULL, NULL, NULL, 4),
(9, 'kkm', 'Menurut Peraturan SOLAS, semua tangki pemberat air laut khusus pada kapal tanker minyak harus memiliki sistem pencegahan korosi yang efisien seperti lapisan pelindung keras atau yang setara. Mengenai lapisan, apakah SOLAS menetapkan persyaratan warna?', NULL, NULL, NULL, 4),
