(402, 'va_3', 'Ide dan proyek baru terkadang mengalihkan perhatian saya dari proyek sebelumnya.', NULL, NULL, NULL, 3),
(403, 'va_3', 'Minat atau ketertarikan saya sering berubah dari tahun ke tahun.', NULL, NULL, NULL, 3),
