--
-- Table structure for table `reports`
--

CREATE TABLE `reports` (
  `id` bigint NOT NULL,
  `vessel_name` varchar(255) DEFAULT NULL,
  `nama` varchar(255) DEFAULT NULL,
  `jabatan` varchar(255) DEFAULT NULL,
  `kondite_review` int DEFAULT NULL,
  `kpi_vessel` int DEFAULT NULL,
  `performance_score` int DEFAULT NULL,
  `value_assessment` int DEFAULT NULL,
  `assessment_center` int DEFAULT NULL,
  `potential_score` int DEFAULT NULL,
  `hav_mapping` varchar(255) DEFAULT NULL,
  `competency_gap_analysis` varchar(255) DEFAULT NULL,
  `talent_classified` varchar(255) DEFAULT NULL,
  `idp_program` varchar(100) DEFAULT NULL,
  `idp` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `seaman_code` varchar(50) NOT NULL,
  `seafarer_code` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `readiness` varchar(50) NOT NULL,
  `certificate` varchar(255) DEFAULT NULL,
  `total_gap` int DEFAULT NULL,
  `strength` int DEFAULT NULL,
  `hav_quadran2` int DEFAULT NULL,
  `talent_classified2` varchar(100) DEFAULT NULL,
  `certificate_eligible` varchar(100) DEFAULT NULL,
  `age` varchar(25) DEFAULT NULL,
  `hav_quadran` int DEFAULT NULL,
  `tanggal_lahir` varchar(20) DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `warning_letter` text,
  `case_history` text,
  `year_of_case` varchar(50) DEFAULT NULL,
  `vessel_history` text,
  `training_completed` text,
  `training_planned` text,
  `mentoring_completed` text,
  `mentoring_planned` text,
  `coaching_completed` text,
  `coaching_planned` text,
  `data_incumbent` varchar(255) DEFAULT NULL,
  `succession_vessel` varchar(255) DEFAULT NULL,
  `succession_rank` varchar(255) DEFAULT NULL,
  `idp_start` date DEFAULT NULL,
  `idp_mentor` varchar(255) DEFAULT NULL,
  `idp_coach` varchar(255) DEFAULT NULL,
  `user` varchar(100) DEFAULT NULL,
  `readiness_month` int DEFAULT NULL,
  `education_fulfillment_months` int DEFAULT NULL,
  `total_readiness_update_months` int DEFAULT NULL,
  `keterangan` text,
  `tm_nm` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

