-- Migrate existing gap_competencies data
INSERT INTO `gap_competencies` (`report_id`, `competency_type_id`, `program`, `gap_level`, `priority`)
SELECT 
    r.id AS report_id,
    ct.id AS competency_type_id,
    COALESCE(r.idp_program, 'SDP') AS program,
    'MEDIUM' AS gap_level,
    1 AS priority
FROM reports r
CROSS JOIN competency_types ct
WHERE r.competency_gap_analysis IS NOT NULL 
  AND r.competency_gap_analysis != '0'
  AND r.competency_gap_analysis != ''
  AND FIND_IN_SET(ct.code, REPLACE(r.competency_gap_analysis, '; ', ',')) > 0;

-- Create training_schedules table
CREATE TABLE `training_schedules` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `program` varchar(10) NOT NULL DEFAULT 'SDP',
  `competency_code` varchar(10) NOT NULL,
  `training_topic` varchar(255) NOT NULL,
  `category` enum('M','NM') NOT NULL DEFAULT 'M',
  `material_type` enum('1','2') NOT NULL DEFAULT '1',
  `scheduled_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_program` (`program`),
  KEY `idx_competency_code` (`competency_code`),
  KEY `idx_scheduled_date` (`scheduled_date`),
  KEY `idx_category` (`category`),
  KEY `idx_material_type` (`material_type`),
  UNIQUE KEY `unique_schedule` (`program`, `competency_code`, `material_type`, `scheduled_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `training_schedules` 
ADD COLUMN `competency_type_id` bigint(20) NULL AFTER `competency_code`,
ADD KEY `idx_competency_type_id` (`competency_type_id`);

ALTER TABLE `training_schedules` 
ADD CONSTRAINT `fk_training_schedules_competency_type` 
FOREIGN KEY (`competency_type_id`) REFERENCES `competency_types` (`id`) ON DELETE SET NULL;

UPDATE `training_schedules` ts 
JOIN `competency_types` ct ON ts.competency_code = ct.code 
SET ts.competency_type_id = ct.id
WHERE ts.competency_type_id IS NULL;

SELECT 'Competency Types Created:' AS info, COUNT(*) AS count FROM competency_types;
SELECT 'Gap Competencies Migrated:' AS info, COUNT(*) AS count FROM gap_competencies;
SELECT 'Training Schedules Linked:' AS info, COUNT(*) AS count FROM training_schedules WHERE competency_type_id IS NOT NULL;

SELECT 
    r.nama AS participant_name,
    ct.code AS competency_code,
    ct.name AS competency_name,
    gc.program,
    gc.gap_level,
    gc.priority
FROM gap_competencies gc
JOIN reports r ON gc.report_id = r.id
JOIN competency_types ct ON gc.competency_type_id = ct.id
LIMIT 10;


